import { defineConfig, devices } from '@playwright/test';
import { BASE_URL } from './e2e/support/env';

/**
 * E2E configuration for the wizard (CLAUDE.md section 4: @playwright/test, no schematics).
 *
 * The tests run against the docker compose stack with the seed (ADR-0002 topology): the `frontend`
 * nginx container serves the Angular build and proxies the read-only content API on one origin;
 * Strapi keeps its own port for the admin panel and for the Node-side test setup. Nothing is
 * mocked, except where a test aborts a request in the browser on purpose (US-01-AC-17).
 *
 * Environment variables are read in e2e/support/env.ts (defaults from the ADR-0002 topology).
 * There is no `webServer` block: the stack is started by `docker compose up`, not by Playwright.
 */
export default defineConfig({
  testDir: './e2e',
  testMatch: '**/*.spec.ts',
  // One admin login per run (Strapi rate-limits it); see e2e/global-setup.ts.
  globalSetup: './e2e/global-setup.ts',
  // One worker, in file order: us-01-config-change adds and removes a published field, which the
  // other files must never see (they assert the exact field list).
  workers: 1,
  fullyParallel: false,
  retries: 0,
  forbidOnly: !!process.env['CI'],
  reporter: [['list'], ['html', { open: 'never' }]],
  use: {
    baseURL: BASE_URL,
    locale: 'es-CO',
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
  },
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],
});
import { request } from '@playwright/test';
import { STRAPI_URL, adminCredentials } from './support/env';
import { openSharedAdminSession } from './support/strapi-admin';

/**
 * One Strapi admin login per test run. Strapi rate-limits the admin login (5 per 5 minutes per
 * email and IP), so the tests that write content (US-01-AC-03, US-01-AC-28) reuse this session
 * instead of logging in themselves. The JWT stays in the Node environment of the runner and its
 * workers: it is never logged and never reaches a browser context.
 */
export default async function globalSetup(): Promise<void> {
  const { email, password } = adminCredentials();
  const api = await request.newContext({ baseURL: STRAPI_URL });
  try {
    await openSharedAdminSession(api, email, password);
  } finally {
    await api.dispose();
  }
}
/**
 * Environment of the e2e run. Defaults follow the ADR-0002 topology; nothing here is a secret.
 *
 *   E2E_BASE_URL            origin of the nginx front end (same origin for the app and /api)
 *   E2E_STRAPI_URL          Strapi's own port: admin panel, direct anonymous reads, test setup
 *   STRAPI_ADMIN_EMAIL      development super admin created by the Strapi bootstrap (ADR-0002)
 *   STRAPI_ADMIN_PASSWORD   its password. Used only by the Node test process (US-01-AC-03)
 *
 * The admin credentials have no default on purpose. Put them in the git-ignored env file of the
 * repository root, or export them; they are never printed and never reach a browser context.
 */
try {
  // Node >= 20.12. A missing file is fine: values already in the environment win.
  process.loadEnvFile('../.env');
} catch {
  /* no env file: rely on the process environment */
}

export const BASE_URL = process.env['E2E_BASE_URL'] ?? 'http://localhost:8080';
export const STRAPI_URL = process.env['E2E_STRAPI_URL'] ?? 'http://localhost:1337';

export function adminCredentials(): { email: string; password: string } {
  const email = process.env['STRAPI_ADMIN_EMAIL'];
  const password = process.env['STRAPI_ADMIN_PASSWORD'];
  if (!email || !password) {
    // A hard failure, not a skip: US-01-AC-03 cannot be verified without the write flow of ADR-0002.
    throw new Error('STRAPI_ADMIN_EMAIL and STRAPI_ADMIN_PASSWORD must be set for the US-01-AC-03 test (see e2e/support/env.ts).');
  }
  return { email, password };
}
import { expect, type Locator, type Page } from '@playwright/test';

/**
 * Helpers for the step 1 form. Everything is found the way a person or assistive technology finds
 * it: by label, by role, by visible text. Values are fictitious (specs/US-01/seed-fields.md).
 */

export const CO_LABELS = [
  'Tipo de documento',
  'Número de documento',
  'Nombre completo',
  'Fecha de nacimiento',
  'Ciudad',
  'Placa',
  'Marca',
  'Línea',
  'Modelo (año)',
  'Autorizo el tratamiento de mis datos personales.',
];

export const CL_LABELS = [
  'RUT',
  'Nombre completo',
  'Fecha de nacimiento',
  'Ciudad',
  'Patente',
  'Marca',
  'Modelo',
  'Año',
  'Acepto el tratamiento de mis datos personales.',
];

/** US-01-AC-04 values for Colombia. Selects use the visible option text. */
export const CO_VALID: Record<string, string | boolean> = {
  'Tipo de documento': 'Cédula de ciudadanía',
  'Número de documento': '1012345678',
  'Nombre completo': 'Ana Prueba Ficticia',
  'Fecha de nacimiento': '1990-05-15',
  Ciudad: 'Medellín',
  Placa: 'ABC123',
  Marca: 'Mazda',
  Línea: '3 Touring',
  'Modelo (año)': '2022',
  'Autorizo el tratamiento de mis datos personales.': true,
};

export const CO_CONSENT = 'Autorizo el tratamiento de mis datos personales.';

function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** A label, allowing the optional required marker ("Placa *") a form may add after it. */
export function labelPattern(label: string): RegExp {
  return new RegExp(`^\\s*${escapeRegExp(label)}\\s*(\\*|\\(obligatorio\\))?\\s*$`);
}

export function field(page: Page, label: string): Locator {
  return page.getByLabel(labelPattern(label));
}

export function continuar(page: Page): Locator {
  return page.getByRole('button', { name: 'Continuar' });
}

/**
 * The visible labels of the form, in document order. `<label>` has no ARIA role that lists them,
 * so this is the one CSS locator; the order of labels is what AC-01 asserts.
 */
export async function visibleLabels(page: Page): Promise<string[]> {
  const texts = await page.locator('label').allInnerTexts();
  return texts.map((t) => t.replace(/\*/g, '').replace(/\s+/g, ' ').trim()).filter((t) => t.length > 0);
}

/** Fill one control by label with the gesture that suits its kind. */
export async function fillField(page: Page, label: string, value: string | boolean): Promise<void> {
  const control = field(page, label);
  const tag = await control.evaluate((el) => el.tagName.toLowerCase());
  const type = await control.evaluate((el) => (el as HTMLInputElement).type);
  if (tag === 'select') {
    await control.selectOption({ label: value as string });
  } else if (type === 'checkbox') {
    if (value) await control.check();
    else await control.uncheck();
  } else {
    await control.fill(value as string);
  }
}

/** Fill the whole Colombia form; `overrides` replace values, `null` leaves a field untouched. */
export async function fillColombia(page: Page, overrides: Record<string, string | boolean | null> = {}): Promise<void> {
  const values: Record<string, string | boolean | null> = { ...CO_VALID, ...overrides };
  for (const [label, value] of Object.entries(values)) {
    if (value === null) continue;
    await fillField(page, label, value);
  }
}

export async function expectDescribedBy(page: Page, label: string, message: string): Promise<void> {
  await expect(field(page, label)).toHaveAccessibleDescription(new RegExp(escapeRegExp(message)));
}

/** Escape text for use inside a RegExp built by a test. */
export const escape = escapeRegExp;
import { expect, type APIRequestContext, type Locator, type Page } from '@playwright/test';
import { continuar, field, fillColombia, fillField } from './form';
import type { AdminSession, ScopedToken } from './strapi-admin';

/**
 * Helpers for step 2 (the plan list) and for the US-02 write flow of the e2e tests. Everything on
 * the page is found by role, name or visible text: plans are native radios (US-02-Q-13), so a plan
 * is `getByRole('radio', { name: <plan name> })`. Values are fictitious (specs/US-02/seed-plans.md).
 */

export const HEADING = 'Elige tu plan';
export const TITLE = 'Elige tu plan | Cotizador de seguro de auto';

/** The browser clock of every US-02 e2e test, so that the prices are stable (spec section 11). */
export const TODAY = new Date('2026-11-21T10:00:00');

export const CO_PLAN_NAMES = ['Plan Básico', 'Plan Clásico', 'Plan Total'];
export const CL_PLAN_NAMES = ['Plan Esencial', 'Plan Protegido', 'Plan Premium'];
/** Final prices of the seed with the step 1 values below at 2026-11-21 (US-02-AC-07). */
export const CO_PRICES = ['$935.000', '$1.540.000', '$2.310.000'];
export const CL_PRICES = ['$319.000', '$528.000', '$792.000'];
/** Seeded plans that are never offered: draft only or inactive (US-02-AC-01, AC-08). */
export const CO_HIDDEN_NAMES = ['Plan Joven', 'Plan Total Plus'];
export const CL_HIDDEN_NAMES = ['Plan Flex', 'Plan Premium Plus'];

export const CL_CONSENT = 'Acepto el tratamiento de mis datos personales.';

/** "I completed step 1 in Chile" of US-02 spec section 5. */
export const CL_VALID: Record<string, string | boolean> = {
  RUT: '12.345.678-5',
  'Nombre completo': 'Ana Prueba Ficticia',
  'Fecha de nacimiento': '1990-05-15',
  Ciudad: 'Santiago',
  Patente: 'BCDF12',
  Marca: 'Kia',
  Modelo: 'Rio 5',
  Año: '2022',
  [CL_CONSENT]: true,
};

export async function fillChile(page: Page, overrides: Record<string, string | boolean | null> = {}): Promise<void> {
  const values: Record<string, string | boolean | null> = { ...CL_VALID, ...overrides };
  for (const [label, value] of Object.entries(values)) {
    if (value === null) continue;
    await fillField(page, label, value);
  }
}

/** A price as the page may write it: whitespace between the symbol and the digits is allowed (BR-03). */
export function pricePattern(price: string): RegExp {
  const digits = price.replace(/[^\d.]/g, '').replace(/\./g, '\\.');
  return new RegExp(`\\$\\s*${digits}(?![\\d.])`);
}

export function plan(page: Page, name: string): Locator {
  return page.getByRole('radio', { name, exact: true });
}

export function plans(page: Page): Locator {
  return page.getByRole('radio');
}

export function atras(page: Page): Locator {
  return page.getByRole('button', { name: 'Atrás' });
}

/** The plan names shown, in order (each option's accessible name is its plan name, US-02-AC-17). */
export async function expectPlanNames(page: Page, names: string[]): Promise<void> {
  await expect(plans(page)).toHaveCount(names.length);
  for (const [index, name] of names.entries()) {
    await expect(plans(page).nth(index)).toHaveAccessibleName(name);
  }
}

/** The final price of each plan is part of its accessible description (US-02-AC-17). */
export async function expectPrices(page: Page, names: string[], prices: string[]): Promise<void> {
  for (const [index, name] of names.entries()) {
    await expect(plan(page, name)).toHaveAccessibleDescription(pricePattern(prices[index]));
  }
}

/** Every control of step 1 shows the value that was entered (US-01-AC-04, AC-20, AC-21); no error is shown. */
export async function expectEntered(page: Page, values: Record<string, string | boolean>): Promise<void> {
  for (const [label, value] of Object.entries(values)) {
    const control = field(page, label);
    const tag = await control.evaluate((el) => el.tagName.toLowerCase());
    const type = await control.evaluate((el) => (el as HTMLInputElement).type);
    if (tag === 'select') {
      await expect.poll(() => control.evaluate((el) => (el as HTMLSelectElement).selectedOptions[0]?.textContent?.trim()), { message: label }).toBe(value);
    } else if (type === 'checkbox') {
      await (value ? expect(control).toBeChecked() : expect(control).not.toBeChecked());
    } else {
      await expect(control, label).toHaveValue(value as string);
    }
    await expect(control).not.toHaveAttribute('aria-invalid', 'true');
  }
}

/** Complete step 1 for Colombia (US-01-AC-04 values) and activate "Continuar". */
export async function reachPlansInColombia(page: Page): Promise<void> {
  await page.clock.setFixedTime(TODAY);
  await page.goto('/co/datos');
  await expect(field(page, 'Placa')).toBeVisible();
  await fillColombia(page);
  await continuar(page).click();
  await expect(page).toHaveURL(/\/co\/planes$/);
  await expect(page.getByRole('heading', { level: 1, name: HEADING })).toBeVisible();
}

export async function reachPlansInChile(page: Page): Promise<void> {
  await page.clock.setFixedTime(TODAY);
  await page.goto('/cl/datos');
  await expect(field(page, 'Patente')).toBeVisible();
  await fillChile(page);
  await continuar(page).click();
  await expect(page).toHaveURL(/\/cl\/planes$/);
  await expect(page.getByRole('heading', { level: 1, name: HEADING })).toBeVisible();
}

// ---------------------------------------------------------------------------------------------
// Write flow for US-02-AC-12 (ADR-0005 general rule, spec 7.5): Node process only
// ---------------------------------------------------------------------------------------------

const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;
/** Exactly these three permissions (spec 7.5): create and delete of `plan`, and `country.find` for the relation. */
export const PLAN_TOKEN_SCOPE = ['api::plan.plan.create', 'api::plan.plan.delete', 'api::country.country.find'];

async function expectOk(response: { ok(): boolean; status(): number }, what: string): Promise<void> {
  // Status and a fixed description only: response bodies may carry tokens.
  if (!response.ok()) throw new Error(`${what} failed with HTTP ${response.status()}`);
}

export async function createPlanToken(api: APIRequestContext, session: AdminSession, name: string): Promise<ScopedToken> {
  const response = await api.post('/admin/api-tokens', {
    headers: { Authorization: `Bearer ${session.jwt}` },
    data: {
      name,
      description: 'Temporary token of the US-02-AC-12 end-to-end test; deleted in teardown.',
      type: 'custom',
      lifespan: SEVEN_DAYS_MS,
      permissions: PLAN_TOKEN_SCOPE,
    },
  });
  await expectOk(response, 'Creating the scoped API token');
  const body = (await response.json()) as { data?: { id?: number; accessKey?: string } };
  if (body.data?.id === undefined || !body.data.accessKey) throw new Error('Strapi returned no API token');
  return { id: body.data.id, accessKey: body.data.accessKey };
}

export interface NewPlan {
  key: string;
  name: string;
  shortDescription: string;
  basePrice: number;
  sortOrder: number;
  isActive: boolean;
  isRecommended: boolean;
  coverages: string[];
}

/** A REST POST publishes immediately unless `status=draft` is passed (ADR-0002, Strapi REST docs). */
export async function createPlan(api: APIRequestContext, token: ScopedToken, countryDocumentId: string, plan: NewPlan): Promise<string> {
  const { coverages, ...attributes } = plan;
  const response = await api.post('/api/plans', {
    headers: { Authorization: `Bearer ${token.accessKey}` },
    data: { data: { ...attributes, coverages: coverages.map((label) => ({ label })), country: { connect: [countryDocumentId] } } },
  });
  await expectOk(response, 'Creating the plan');
  const body = (await response.json()) as { data?: { documentId?: string } };
  if (!body.data?.documentId) throw new Error('Strapi returned no documentId for the new plan');
  return body.data.documentId;
}

export async function deletePlan(api: APIRequestContext, token: ScopedToken, documentId: string): Promise<void> {
  const response = await api.delete(`/api/plans/${documentId}`, { headers: { Authorization: `Bearer ${token.accessKey}` } });
  await expectOk(response, 'Deleting the plan');
}

/** Pre-test cleanup: deletes published plans left with the test's key by a crashed run (read is public). */
export async function deleteStalePlans(api: APIRequestContext, token: ScopedToken, key: string): Promise<void> {
  const response = await api.get('/api/plans', { params: { 'filters[key][$eq]': key, 'pagination[pageSize]': '100' } });
  await expectOk(response, 'Reading leftover plans');
  const body = (await response.json()) as { data?: { documentId?: string }[] };
  for (const stale of body.data ?? []) {
    if (stale.documentId) await deletePlan(api, token, stale.documentId);
  }
}
#!/usr/bin/env bash
# Run the Playwright e2e suite against a running stack, with the documented defaults.
# Exists so that nobody (human or agent) has to rebuild the env line by hand: a hand-built
# `env $VARS` line silently broke the gate once (zsh does not word-split unquoted variables).
#
#   scripts/e2e.sh                     full suite
#   scripts/e2e.sh -g 'AC-24' --repeat-each=10
#   scripts/e2e.sh e2e/us-01-security.spec.ts
#
# Any variable already set in the environment wins over the defaults below. The admin values are
# the fictitious dev defaults from docker-compose.yml (never real credentials).

set -euo pipefail
cd "$(git rev-parse --show-toplevel)/frontend"

export E2E_BASE_URL="${E2E_BASE_URL:-http://localhost:8080}"
export E2E_STRAPI_URL="${E2E_STRAPI_URL:-http://localhost:1337}"
export STRAPI_ADMIN_EMAIL="${STRAPI_ADMIN_EMAIL:-dev.admin@example.com}"
export STRAPI_ADMIN_PASSWORD="${STRAPI_ADMIN_PASSWORD:-DevOnly-Passw0rd}"

exec npx playwright test --reporter=line "$@"

