/// <reference types="node" />
import { describe, expect, it } from 'vitest';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';

/**
 * The review greps of ADR-0008 and ADR-0009 ("Confirmation"), as tests, so that they run in the
 * gate and not only in a reviewer's terminal. They read the production sources of `frontend/src`
 * (test files and the `testing/` helpers excluded) and `frontend/package.json`.
 *
 * US-03-AC-13 / ADR-0009: no `innerHTML`, `outerHTML`, `insertAdjacentHTML`, `bypassSecurityTrust*`
 *   or `DomSanitizer` anywhere in the front end.
 * US-03-AC-15 / ADR-0008: no card, bank or payment-provider vocabulary outside the copy that says
 *   no charge is made; no `autocomplete` token starting with `cc-`; `SimulatedPaymentGateway` does
 *   not inject `HttpClient`; `sessionStorage` is referenced only by `QuoteStore`; the confirmation
 *   is not deferred (`@defer`) or lazy loaded; no new dependency (the list below is the one of
 *   the start of US-03).
 */

const SRC = join(process.cwd(), 'src');

function walk(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    return statSync(path).isDirectory() ? walk(path) : [path];
  });
}

const isTest = (path: string): boolean => /\.spec\.ts$/.test(path) || path.includes(`${join('src', 'testing')}`);
const production = walk(SRC).filter((p) => /\.(ts|html)$/.test(p) && !isTest(p));
const read = (path: string): string => readFileSync(path, 'utf8');
const matches = (pattern: RegExp, files = production): string[] => files.filter((p) => pattern.test(read(p))).map((p) => p.replace(SRC, 'src'));

describe('US-03-AC-13 / ADR-0009 the front end has no HTML string path', () => {
  it('US-03-AC-13 the production sources are found (the guard looks at something)', () => {
    expect(production.length).toBeGreaterThan(20);
  });

  it('US-03-AC-13 no innerHTML, outerHTML, insertAdjacentHTML, bypassSecurityTrust or DomSanitizer in production code', () => {
    expect(matches(/innerHTML|outerHTML|insertAdjacentHTML|bypassSecurityTrust|DomSanitizer/)).toEqual([]);
  });

  it('US-03-AC-13 the renderer exists and binds its content with interpolation only (no property or attribute binding of a span text)', () => {
    const files = production.filter((p) => /rich-text\.(ts|html)$/.test(p));
    expect(files.length).toBeGreaterThan(0);
    for (const file of files) {
      expect(read(file), file).not.toMatch(/\[(innerHTML|href|src|style|class|attr\.[a-z-]+)\]\s*=\s*"[^"]*span/);
    }
  });
});

describe('US-03-AC-15 / ADR-0008 no card data, no payment SDK, no request from the simulation', () => {
  it('US-03-AC-15 no card, bank or payment-provider vocabulary in production code (cc-number, cc-exp, cc-csc, cvv, cvc, iban, stripe, paypal, mercadopago, payu, wompi, webpay)', () => {
    expect(matches(/cc-(number|exp|csc|name)|\bcvv\b|\bcvc\b|\biban\b|stripe|paypal|mercadopago|payu|wompi|webpay/i)).toEqual([]);
  });

  it('US-03-AC-15 no autocomplete token that starts with cc-', () => {
    expect(matches(/autocomplete\s*=\s*["'][^"']*cc-/i)).toEqual([]);
  });

  it('US-03-AC-15 "tarjeta" or "card" appear only in copy that says no charge is made (none today)', () => {
    const hits = production.filter((p) => /tarjeta|\bcard\b/i.test(read(p)) && !/no se (realiza|realizó) ningún cobro/.test(read(p)));
    expect(hits.map((p) => p.replace(SRC, 'src'))).toEqual([]);
  });

  it('US-03-AC-15 SimulatedPaymentGateway does not use HttpClient (the file exists and has no HTTP import)', () => {
    const files = production.filter((p) => p.endsWith('simulated-payment-gateway.ts'));
    expect(files).toHaveLength(1);
    expect(read(files[0])).not.toMatch(/HttpClient|HttpBackend|fetch\(|XMLHttpRequest|sessionStorage|localStorage|@angular\/common\/http/);
  });

  it('US-03-AC-15 the payment gateway boundary has no card-shaped field (number, expiry, cvv, holder)', () => {
    // Both the boundary and its simulated implementation, matched by exact basename.
    const files = production.filter((p) => ['payment-gateway.ts', 'simulated-payment-gateway.ts'].includes(p.split(/[\\/]/).pop() ?? ''));
    expect(files.map((p) => p.split(/[\\/]/).pop()).sort()).toEqual(['payment-gateway.ts', 'simulated-payment-gateway.ts']);
    for (const file of files) expect(read(file), file).not.toMatch(/cardNumber|expiry|expiration|securityCode|holder/i);
  });

  it('US-03-AC-11 sessionStorage is referenced only by QuoteStore (ADR-0003)', () => {
    expect(matches(/sessionStorage/)).toEqual([join('src', 'app', 'core', 'quote-store.ts')]);
  });

  it('US-03-AC-03 the confirmation is not deferred or lazy loaded: no @defer and no loadComponent in the summary feature', () => {
    const summary = production.filter((p) => p.includes(join('features', 'summary')));
    expect(summary.length).toBeGreaterThan(0);
    for (const file of summary) expect(read(file), file).not.toMatch(/@defer|loadComponent|import\(/);
  });

  it('US-03-AC-15 the dependencies of frontend/package.json are exactly those before US-03 (no payment SDK, no markdown or sanitiser library)', () => {
    const pkg = JSON.parse(read(join(process.cwd(), 'package.json'))) as { dependencies: Record<string, string>; devDependencies: Record<string, string> };
    const names = [...Object.keys(pkg.dependencies), ...Object.keys(pkg.devDependencies)];
    for (const forbidden of ['marked', 'markdown-it', 'ngx-markdown', 'dompurify', 'sanitize-html', 'blocks-html-renderer', '@strapi/blocks-react-renderer', 'stripe', '@stripe/stripe-js', 'paypal']) {
      expect(names, forbidden).not.toContain(forbidden);
    }
    for (const version of Object.values({ ...pkg.dependencies, ...pkg.devDependencies })) expect(version).toMatch(/^\d+\.\d+\.\d+/);
  });
});
/**
 * Helpers to run router guards in an injection context, as the router would, without a browser.
 */
import { TestBed } from '@angular/core/testing';
import { isObservable, firstValueFrom } from 'rxjs';
import {
  convertToParamMap,
  RedirectCommand,
  Router,
  UrlSegment,
  type ActivatedRouteSnapshot,
  type CanMatchFn,
  type GuardResult,
  type MaybeAsync,
  type RouterStateSnapshot,
} from '@angular/router';

/** Wait for a guard result whatever its shape (value, promise, observable). */
export async function settleGuard(result: MaybeAsync<GuardResult>): Promise<GuardResult> {
  if (isObservable(result)) return firstValueFrom(result);
  return await result;
}

export function runInContext<T>(fn: () => T): T {
  return TestBed.runInInjectionContext(fn);
}

/**
 * The snapshot a `canActivate` guard of `/:country/planes` receives. The country is offered the
 * ways the router can expose it (own params, parent params), so the guard may read it any of them.
 */
export function stepSnapshot(country: string): ActivatedRouteSnapshot {
  const params = { country };
  const paramMap = convertToParamMap(params);
  const parent = { params, paramMap, parent: null, url: [new UrlSegment(country, {})] };
  return { params, paramMap, parent, url: [new UrlSegment('planes', {})] } as unknown as ActivatedRouteSnapshot;
}

export function stepState(url: string): RouterStateSnapshot {
  return { url } as unknown as RouterStateSnapshot;
}

export function segmentsOf(...paths: string[]): UrlSegment[] {
  return paths.map((p) => new UrlSegment(p, {}));
}

/** Where a guard redirects to, as the serialized address, plus its navigation behaviour. */
export function redirectOf(result: GuardResult): { url: string; replaceUrl: boolean | undefined } | null {
  if (!(result instanceof RedirectCommand)) return null;
  const router = TestBed.inject(Router);
  return { url: router.serializeUrl(result.redirectTo), replaceUrl: result.navigationBehaviorOptions?.replaceUrl };
}

/** The third `canMatch` argument (the partial snapshot); the guard under test must not need it. */
export function emptyMatchSnapshot(): Parameters<CanMatchFn>[2] {
  return {} as Parameters<CanMatchFn>[2];
}
/**
 * A scripted stand-in for the Strapi content API behind the same-origin proxy (ADR-0002), built on
 * Angular's `HttpTestingController`. Tests change `countries` and `fields` to script success, an
 * HTTP error, or no answer at all.
 *
 * Why `drain()` exists: in a zoneless TestBed, `fixture.whenStable()` waits for in-flight HTTP
 * requests, so a test that awaits it before answering the request never finishes. `drain()`
 * answers requests as they appear until the application has been idle for a few macrotasks.
 *
 * It matches requests by URL only (`/api/countries`, `/api/form-fields`, `/api/plans` and `/api/terms` with
 * `filters[country][code][$eq]=<CODE>`), so the tests do not depend on how the API client is built.
 */
import { HttpTestingController, TestRequest } from '@angular/common/http/testing';
import { vi } from 'vitest';
import { seedPlanItems } from './plan-fixtures';
import { seedTermsItems } from './terms-fixtures';
import { seedCountryItems, seedStrapiItems, strapiListResponse, type StrapiItem } from './seed-fixtures';

export type Behaviour = StrapiItem[] | 'error' | 'hang';

export interface RecordedRequest {
  method: string;
  /** The URL with its query string, percent-decoded (brackets and `$` readable). */
  url: string;
  kind: 'countries' | 'form-fields' | 'plans' | 'terms' | 'other';
  /** For `form-fields`, `plans` and `terms`: the value of `filters[country][code][$eq]`. */
  countryCode?: string;
  /** True when the request carried an `Authorization` header. */
  hasAuthorization: boolean;
}

/** Let the event loop run one macrotask (works with real and with fake timers). */
export async function pump(): Promise<void> {
  if (vi.isFakeTimers()) {
    await vi.advanceTimersByTimeAsync(0);
  } else {
    await new Promise<void>((resolve) => setTimeout(resolve, 0));
  }
}

export class ContentServer {
  countries: Behaviour = seedCountryItems();
  fields: Record<string, Behaviour> = { CO: seedStrapiItems('CO'), CL: seedStrapiItems('CL') };
  /** What `/api/plans` answers per country code (US-02): the offered seed plans by default. */
  plans: Record<string, Behaviour> = { CO: seedPlanItems('CO'), CL: seedPlanItems('CL') };
  /** What `/api/terms` answers per country code (US-03): the published seed terms by default. */
  terms: Record<string, Behaviour> = { CO: seedTermsItems('CO'), CL: seedTermsItems('CL') };
  readonly requests: RecordedRequest[] = [];

  constructor(private readonly http: HttpTestingController) {}

  requestsOf(kind: RecordedRequest['kind']): RecordedRequest[] {
    return this.requests.filter((r) => r.kind === kind);
  }

  /** Answer every request that appears, until nothing new arrives for three macrotasks. */
  async drain(): Promise<void> {
    let idle = 0;
    while (idle < 3) {
      await pump();
      const open = this.http.match(() => true);
      if (open.length === 0) {
        idle++;
        continue;
      }
      idle = 0;
      for (const req of open) this.answer(req);
    }
  }

  private answer(req: TestRequest): void {
    const url = decodeURIComponent(req.request.urlWithParams);
    const hasAuthorization = req.request.headers.has('Authorization');
    if (req.request.method === 'GET' && /^(https?:\/\/[^/]+)?\/api\/countries(\?|$)/.test(url)) {
      this.requests.push({ method: 'GET', url, kind: 'countries', hasAuthorization });
      this.respond(req, this.countries);
      return;
    }
    if (req.request.method === 'GET' && /^(https?:\/\/[^/]+)?\/api\/form-fields(\?|$)/.test(url)) {
      const code = /filters\[country\]\[code\]\[\$eq\]=([^&]+)/.exec(url)?.[1];
      this.requests.push({ method: 'GET', url, kind: 'form-fields', countryCode: code, hasAuthorization });
      this.respond(req, (code !== undefined ? this.fields[code] : undefined) ?? []);
      return;
    }
    if (req.request.method === 'GET' && /^(https?:\/\/[^/]+)?\/api\/plans(\?|$)/.test(url)) {
      const code = /filters\[country\]\[code\]\[\$eq\]=([^&]+)/.exec(url)?.[1];
      this.requests.push({ method: 'GET', url, kind: 'plans', countryCode: code, hasAuthorization });
      this.respond(req, (code !== undefined ? this.plans[code] : undefined) ?? []);
      return;
    }
    if (req.request.method === 'GET' && /^(https?:\/\/[^/]+)?\/api\/terms(\?|$)/.test(url)) {
      const code = /filters\[country\]\[code\]\[\$eq\]=([^&]+)/.exec(url)?.[1];
      this.requests.push({ method: 'GET', url, kind: 'terms', countryCode: code, hasAuthorization });
      this.respond(req, (code !== undefined ? this.terms[code] : undefined) ?? []);
      return;
    }
    this.requests.push({ method: req.request.method, url, kind: 'other', hasAuthorization });
    req.flush({ error: { status: 404, name: 'NotFoundError', message: 'Not Found' } }, { status: 404, statusText: 'Not Found' });
  }

  private respond(req: TestRequest, behaviour: Behaviour): void {
    if (behaviour === 'hang') return; // never answered: the client's own timeout must fire
    if (behaviour === 'error') {
      req.flush(
        { data: null, error: { status: 500, name: 'InternalServerError', message: 'Internal Server Error' } },
        { status: 500, statusText: 'Internal Server Error' },
      );
      return;
    }
    req.flush(strapiListResponse(behaviour));
  }
}

