import type { RGB, RGBA } from './contrast';
import { hexToRgb } from './contrast';

export interface Decl {
  /** The preludes of the enclosing blocks, outermost first (`['@media (...)', '.card']`). */
  stack: string[];
  prop: string;
  value: string;
}

export interface Block {
  stack: string[];
  prelude: string;
}

export function stripComments(css: string): string {
  return css.replace(/\/\*[\s\S]*?\*\//g, '');
}

/** Split `text` at top-level commas (outside parentheses and quotes). */
export function splitTopLevel(text: string, separator = ','): string[] {
  const parts: string[] = [];
  let depth = 0;
  let quote: string | null = null;
  let current = '';
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (quote) {
      current += ch;
      if (ch === quote && text[i - 1] !== '\\') quote = null;
      continue;
    }
    if (ch === '"' || ch === "'") quote = ch;
    if (ch === '(') depth++;
    if (ch === ')') depth--;
    if (ch === separator && depth === 0) {
      parts.push(current);
      current = '';
      continue;
    }
    current += ch;
  }
  parts.push(current);
  return parts;
}

export function parseCss(css: string): { decls: Decl[]; blocks: Block[] } {
  const text = stripComments(css);
  const decls: Decl[] = [];
  const blocks: Block[] = [];
  const stack: string[] = [];
  let buffer = '';
  let paren = 0;
  let quote: string | null = null;

  const flush = (): void => {
    const raw = buffer.trim();
    buffer = '';
    if (raw === '' || raw.startsWith('@')) return;
    const colon = raw.indexOf(':');
    if (colon < 0) return;
    const prop = raw.slice(0, colon).trim();
    const value = raw.slice(colon + 1).replace(/!important\s*$/i, '').trim();
    decls.push({ stack: [...stack], prop: prop.startsWith('--') ? prop : prop.toLowerCase(), value });
  };

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (quote) {
      buffer += ch;
      if (ch === quote && text[i - 1] !== '\\') quote = null;
      continue;
    }
    if (ch === '"' || ch === "'") {
      quote = ch;
      buffer += ch;
      continue;
    }
    if (ch === '(') paren++;
    if (ch === ')') paren--;
    if (paren > 0 || ch === '(' || ch === ')') {
      buffer += ch;
      continue;
    }
    if (ch === '{') {
      const prelude = buffer.trim().replace(/\s+/g, ' ');
      blocks.push({ stack: [...stack], prelude });
      stack.push(prelude);
      buffer = '';
      continue;
    }
    if (ch === '}') {
      flush();
      stack.pop();
      continue;
    }
    if (ch === ';') {
      flush();
      continue;
    }
    buffer += ch;
  }
  flush();
  return { decls, blocks };
}

// ---------------------------------------------------------------------------------------------
// var() resolution
// ---------------------------------------------------------------------------------------------

/** Find the index of the `)` that closes the `(` at `open`. */
function closingParen(text: string, open: number): number {
  let depth = 0;
  for (let i = open; i < text.length; i++) {
    if (text[i] === '(') depth++;
    if (text[i] === ')') {
      depth--;
      if (depth === 0) return i;
    }
  }
  throw new Error(`Unbalanced parenthesis in "${text}"`);
