/** Remove every `var(...)` (balanced) from a value, leaving a space in its place. */
export function stripVars(value: string): string {
  let out = value;
  for (;;) {
    const at = out.search(/\bvar\(/);
    if (at < 0) return out;
    const open = out.indexOf('(', at);
