// tokens.css: tiers, categories, reduced-motion tokens, fonts
// ---------------------------------------------------------------------------------------------

export const SEMANTIC_PREFIXES = [
  '--color-',
  '--font-',
  '--text-',
  '--leading-',
  '--tracking-',
  '--weight-',
  '--space-',
  '--size-',
  '--radius-',
  '--border-',
  '--shadow-',
  '--gradient-',
  '--texture-',
  '--duration-',
  '--delay-',
  '--ease-',
  '--motion-',
  '--z-',
  '--breakpoint-',
