    const file = tokens();
    expect(file.accentKeys().sort()).toEqual(['cl', 'co']);
    const evaluated = evaluate(file, pairs().filter((r) => r.fg === '--color-country-accent'));
    expect(new Set(evaluated.map((r) => r.accent))).toEqual(new Set(['brand', 'co', 'cl']));
