  });

  it('US-04-AC-09 an injected locale that offers getWeekInfo() is used', () => {
    expect(firstDayOfWeek('xx', () => ({ getWeekInfo: () => ({ firstDay: 7 }) }))).toBe(7);
    expect(firstDayOfWeek('xx', () => ({ getWeekInfo: () => ({ firstDay: 6 }) }))).toBe(6);
