      expect(rows.find((r) => normalise(r.textContent) === 'Medellín')?.querySelector('svg')?.getAttribute('aria-hidden')).toBe('true');
      expect(rows.filter((r) => r.getAttribute('aria-selected') === 'true')).toHaveLength(1);
